/// origin child is represented as a distinct boundary rather than folded into its parent.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct FrameDescriptor {
    /// Opaque frame identifier, unique within a tab. Every local and out-of-process frame has its own
    /// identifier, origin, epoch, revision, and node namespace.
    pub frame_id: FrameId,
    /// Opaque frame identifier, unique within a tab. Every local and out-of-process frame has its own
    /// identifier, origin, epoch, revision, and node namespace.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub parent_frame_id: Option<FrameId>,
    pub is_main_frame: bool,
    /// Whether this frame is hosted in a different renderer process than its parent.
    pub is_out_of_process: bool,
    pub is_cross_origin_to_parent: bool,
    /// Browser-owned security context of an observed document. The renderer never supplies these
    /// values.
    pub origin_metadata: OriginMetadata,
    /// Opaque page epoch assigned by the browser broker. It changes whenever previously issued semantic
    /// handles must not be used for action: committed cross-document navigation, frame or renderer
    /// replacement, prerender activation, security-origin transition, broker reconciliation after a
    /// crash, an explicit broker invalidation, and back/forward cache restore unless the validation
    /// spike proves an equally safe alternative. Compare epochs for equality only; ordering across
    /// frames or sessions carries no meaning. Whether back/forward cache restore always allocates a new
    /// epoch is \[Open (OD-029)\].
    pub page_epoch: PageEpoch,
    /// Monotonically increasing revision within one active page epoch. It advances whenever a mutation
    /// can invalidate a previously observed node, relationship, action precondition, or relevant value.
    /// Revisions from different epochs or frames are not comparable.
    pub graph_revision: GraphRevision,
    /// Browser-owned lifecycle state of the observed document. Only ACTIVE is eligible for action.
    /// Closed enumeration: a consumer that receives a value outside this list MUST treat the message as
    /// unsupported and fail closed, and MUST NOT coerce the value to a known member (protocol section
    /// 6.2).
    pub lifecycle_state: DocumentLifecycleState,
    /// Whether this frame contributed nodes to the snapshot.
    pub included: bool,
    /// Why a frame present in the browser-owned frame tree contributed no nodes. A hidden third-party
    /// frame is not observed merely because it exists; which cross-origin child-frame content may enter
    /// a task is \[Open (OD-045)\]. Closed enumeration: a consumer that receives a value outside this
    /// list MUST treat the message as unsupported and fail closed, and MUST NOT coerce the value to a
    /// known member (protocol section 6.2).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub exclusion_reason: Option<FrameExclusionReason>,
    /// Who authored these bytes. This is a different question from Sensitivity, which says how much
    /// harm their disclosure would cause, and the two axes are independent: a bank statement is highly
    /// sensitive and FIRST_PARTY_DOCUMENT, while a comment on the same page is not sensitive at all and
    /// is USER_GENERATED_CONTENT. A consumer MUST NOT derive one axis from the other. The order of this
    /// enumeration is wire order and is not a trust ordering. An absent label is UNKNOWN_UNTRUSTED,
    /// never an unlabelled default, and a derived value carries the least trusted label of its inputs.
    /// Frame-level authorship is browser-owned: a renderer that supplies USER_AUTHORED, TAFFY_AUTHORED,
    /// or MODEL_AUTHORED is refused the same way a renderer-reported origin is overwritten. Page
    /// content, a model, and a renderer can each lower a label and none of them can raise one. Which
    /// authors are named, and whether document-, image-, media- and search-derived content are distinct
    /// members, is \[Open (OD-082)\]. Closed enumeration: a consumer that receives a value outside this
    /// list MUST treat the message as unsupported and fail closed, and MUST NOT coerce the value to a
    /// known member (protocol section 6.2).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub content_trust: Option<ContentTrust>,
}

