/// One bounded semantic observation of a live document, assembled by the browser broker from one or
/// more frame endpoints. A snapshot is evidence, not authority: nothing in it authorizes an action,
/// and every handle it carries dies with its page epoch.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct PageSnapshot {
    /// Wire protocol version in major.minor form. The current value lives only in bip.version.json;
    /// this schema constrains the shape, never the number.
    pub schema_version: ProtocolVersion,
    /// Opaque snapshot identifier, unique within a profile session.
    pub snapshot_id: SnapshotId,
    /// Opaque observation request identifier. Exactly one terminal response is delivered per request.
    pub request_id: RequestId,
    /// Opaque browser profile identifier. An incognito profile identifier exists only in memory and is
    /// destroyed with its context.
    pub profile_id: ProfileId,
    /// Opaque browser window identifier, unique within a profile.
    pub browser_window_id: BrowserWindowId,
    /// Opaque tab identifier, unique within a profile. A closed tab's identifier is never reassigned.
    pub tab_id: TabId,
    /// Opaque frame identifier, unique within a tab. Every local and out-of-process frame has its own
    /// identifier, origin, epoch, revision, and node namespace.
    pub root_frame_id: FrameId,
    /// Opaque page epoch assigned by the browser broker. It changes whenever previously issued semantic
    /// handles must not be used for action: committed cross-document navigation, frame or renderer
    /// replacement, prerender activation, security-origin transition, broker reconciliation after a
    /// crash, an explicit broker invalidation, and back/forward cache restore unless the validation
    /// spike proves an equally safe alternative. Compare epochs for equality only; ordering across
    /// frames or sessions carries no meaning. Whether back/forward cache restore always allocates a new
    /// epoch is \[Open (OD-029)\].
    pub page_epoch: PageEpoch,
    /// Monotonically increasing revision within one active page epoch. It advances whenever a mutation
    /// can invalidate a previously observed node, relationship, action precondition, or relevant value.
    /// Revisions from different epochs or frames are not comparable.
    pub graph_revision: GraphRevision,
    /// Strictly increasing per-epoch sequence number emitted by a frame endpoint. The broker discards
    /// duplicates and out-of-order events; a detected gap invalidates delta state and forces a fresh
    /// snapshot.
    pub event_sequence: EventSequence,
    /// Browser-owned lifecycle state of the observed document. Only ACTIVE is eligible for action.
    /// Closed enumeration: a consumer that receives a value outside this list MUST treat the message as
    /// unsupported and fail closed, and MUST NOT coerce the value to a known member (protocol section
    /// 6.2).
    pub lifecycle_state: DocumentLifecycleState,
    /// Classified navigation metadata for the observed document. The browser broker's committed
    /// navigation record is the authority; a renderer-reported URL never overrides it. Full URLs, query
    /// strings, and fragments appear only when the task and provider policy permit, which the
    /// disclosure field states explicitly.
    pub committed_url_metadata: UrlMetadata,
    /// Browser-owned security context of an observed document. The renderer never supplies these
    /// values.
    pub origin_metadata: OriginMetadata,
    /// A reading of a monotonic clock in milliseconds. BIP carries no wall-clock timestamps, so a
    /// message cannot leak browsing time across a trust boundary.
    pub capture_time_monotonic_ms: MonotonicMillis,
    /// How much of a document one request covers. Closed enumeration: a consumer that receives a value
    /// outside this list MUST treat the message as unsupported and fail closed, and MUST NOT coerce the
    /// value to a known member (protocol section 6.2).
    pub scope: ObservationScope,
    /// One report per adapter the request named.
    pub adapters: Vec<AdapterReport>,
    pub nodes: Vec<SemanticNode>,
    pub edges: Vec<SemanticEdge>,
    /// The browser-assembled frame tree, including frames that contributed nothing and why.
    pub frames: Vec<FrameDescriptor>,
    /// Explicit account of what a budget removed. Truncation is always stated, including which budget
    /// was reached and whether the omitted data could change the answer. A truncated observation is
    /// never labelled complete.
    pub truncation: Truncation,
    /// Counts of what redaction removed, with no sample of what was removed. Redaction runs in layers:
    /// the renderer adapter omits prohibited values and marks sensitive zones, the browser broker
    /// applies origin, task, incognito, and organization policy, the context engine minimizes fields
    /// for the chosen route, the model adapter enforces provider constraints, and the audit and
    /// telemetry serializers redact independently.
    pub redaction_summary: RedactionSummary,
    pub warnings: Vec<SnapshotWarning>,
    /// The least trusted label carried by any node or frame included in this snapshot. The context
    /// engine reads this without walking the graph.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lowest_content_trust: Option<ContentTrust>,
    /// The exact validated form root echoed from a SECTION request. It is absent for every other scope.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub form_root: Option<FormObservationRoot>,
    /// The exact validated media root echoed from a targeted DOCUMENT request.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub media_root: Option<MediaObservationRoot>,
}

/// Counts of what redaction removed, with no sample of what was removed. Redaction runs in layers:
