/// A bounded request for one observation. The broker clamps every client budget to a process-safe
/// maximum, and a request can never widen the data policy or source scope already granted to the
/// task.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct SnapshotRequest {
    /// Wire protocol version in major.minor form. The current value lives only in bip.version.json;
    /// this schema constrains the shape, never the number.
    pub schema_version: ProtocolVersion,
    /// Opaque observation request identifier. Exactly one terminal response is delivered per request.
    pub request_id: RequestId,
    /// Opaque browser profile identifier. An incognito profile identifier exists only in memory and is
    /// destroyed with its context.
    pub profile_id: ProfileId,
    /// Opaque tab identifier, unique within a profile. A closed tab's identifier is never reassigned.
    pub tab_id: TabId,
    /// Opaque frame identifier, unique within a tab. Every local and out-of-process frame has its own
    /// identifier, origin, epoch, revision, and node namespace.
    pub root_frame_id: FrameId,
    /// The frame this request is addressed to. Distinct from root_frame_id, which names the root of the
    /// observation: an endpoint is that root when the two are equal and a child frame when they are
    /// not, and this is the only way an endpoint can tell. It cannot derive the answer from its own
    /// identity, because the identity it holds is one it minted for itself in a namespace the broker
    /// does not share, so comparing the two compares nothing and has always answered "different".
    /// Optional under the additive rule, and its absence is not a licence to guess: an endpoint that is
    /// not told which frame it is treats itself as a cross-origin child, which raises the sensitivity
    /// floor rather than lowering it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub observed_frame_id: Option<FrameId>,
    /// Required when refreshing an existing binding, absent on a first bind. A mismatch fails the
    /// request rather than returning a snapshot of a different document.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expected_page_epoch: Option<PageEpoch>,
    /// How much of a document one request covers. Closed enumeration: a consumer that receives a value
    /// outside this list MUST treat the message as unsupported and fail closed, and MUST NOT coerce the
    /// value to a known member (protocol section 6.2).
    pub scope: ObservationScope,
    /// Adapters the request names, each marked required or optional.
    pub adapters: Vec<AdapterRequirement>,
    /// Fields the caller wants. Requesting fewer fields is the cheapest form of minimization.
    pub requested_fields: Vec<SemanticField>,
    pub include_child_frames: bool,
    /// The origins whose content the task may observe. An empty list means the root frame's origin
    /// only.
    pub allowed_origins: Vec<Origin>,
    /// A non-negative count of items.
    pub max_nodes: Count,
    /// A count of bytes.
    pub max_text_bytes: ByteCount,
    /// A count of bytes.
    pub max_total_bytes: ByteCount,
    /// A non-negative count of items.
    pub max_depth: Count,
    /// A duration in milliseconds.
    pub deadline_ms: DurationMillis,
    /// Reference to the sensitivity and redaction policy in force for a request. The broker clamps the
    /// request to the policy already granted to the task; a request cannot widen it.
    pub sensitivity_policy_id: SensitivityPolicyId,
    /// A bounded trusted label describing why the task needs this observation. It is chosen by the task
    /// runtime from a local vocabulary and is never page-supplied or model-supplied free text.
    pub task_purpose: String,
    /// Required exactly when scope is SECTION. It names the form node and graph floor that the renderer
    /// must validate before and after collection; no other scope accepts it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub form_root: Option<FormObservationRoot>,
    /// Optional only at DOCUMENT scope and mutually exclusive with form_root. It narrows extraction to
    /// one exact image or video semantic node.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub media_root: Option<MediaObservationRoot>,
}

